#!/usr/bin/env bash
# Reproduce S1+C1 v2x-track submission 'zcal' (model-v2x-track/routed-g1z): test-frame inference with the exact
# checkpoints, merge with the committed model.yaml, compare with the scored zip, repackage the same 50 frames, kit check.
# Generated by common/tools/reproduce_submission.py; scored zip model-v2x-track/routed-g1z/submissions/2026-10-09_zcal/submission_v2x.zip (md5 7fbb973e2c1715dea66d7850b8bde11f).
# Usage: CUDA_VISIBLE_DEVICES=0 bash model-v2x-track/routed-g1z/test/reproduce_zcal.sh
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/../../.."      # the repository root (portable)
source common/env/activate.sh
OUT=model-v2x-track/routed-g1z/test/output/repro_zcal
mkdir -p $OUT
# member g1v2: model-v2x-track/pointpillars-g1v2, checkpoint md5 7c3e9a1c074a67c58933791d2d2b2928
python common/tools/pcdet_predict.py model-v2x-track/pointpillars-g1v2 --ckpt model-v2x-track/pointpillars-g1v2/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/pointpillars-g1v2/test/postprocess.yaml --out $OUT/predictions_g1v2.json
# member g1v3: model-v2x-track/pointpillars-g1v3, checkpoint md5 b330667c29813de83e1f6a355775a83e
python common/tools/pcdet_predict.py model-v2x-track/pointpillars-g1v3 --ckpt model-v2x-track/pointpillars-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/pointpillars-g1v3/test/postprocess.yaml --out $OUT/predictions_g1v3.json
# member ut: model-v2x-track/pointpillars-ut, checkpoint md5 2081ca05e3326bfdbf27794239cdf172
python common/tools/pcdet_predict.py model-v2x-track/pointpillars-ut --ckpt model-v2x-track/pointpillars-ut/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/pointpillars-ut/test/postprocess.yaml --out $OUT/predictions_ut.json
python common/tools/route_predictions.py merge model-v2x-track/routed-g1z --pred g1v2=$OUT/predictions_g1v2.json --pred g1v3=$OUT/predictions_g1v3.json --pred ut=$OUT/predictions_ut.json --out $OUT/predictions.json
python common/tools/reproduce_submission.py model-v2x-track/routed-g1z --tag zcal --compare $OUT/predictions.json
# the 50 realism frames: from the synthetic corpus when it is present (a check that it still gives the scored frames),
# else from the scored zip itself (a fresh clone has no corpus; the zip is in git)
if [ -d "$BDC_DATA/v2x-track/pcdet/g1-v3/points" ]; then SYN=(--syn-split val --syn-list model-v2x-track/routed-g1z/submissions/2026-10-09_zcal/synthetic_ids.txt); else SYN=(--syn-zip model-v2x-track/routed-g1z/submissions/2026-10-09_zcal/submission_v2x.zip --syn-list model-v2x-track/routed-g1z/submissions/2026-10-09_zcal/synthetic_ids.txt); fi
python common/tools/package_submission.py model-v2x-track/routed-g1z --tag repro-zcal --pred $OUT/predictions.json --synthetic pcdet/g1-v3 "${SYN[@]}" --team ${BDC_TEAM:-KarmaRV} --ckpt 'reproduction of zcal' --reproduction
Z=model-v2x-track/routed-g1z/test/output/repro-zcal/submission.zip
python common/tools/check_submission.py --track v2x $Z --official
python common/tools/reproduce_submission.py model-v2x-track/routed-g1z --tag zcal --compare-zip $Z     # predictions and frames against the scored zip
